head.script:
// 화면 리사이징

scwin.gLdMktTp = js_market;
scwin.gEmpNo = js_emp_no;
scwin.gIsurCd;
scwin.gMsgStr;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue(vCurDate); // 일주일전 날짜 cGetMinusDate2(vCurDate, 7)
        edt_EDate.setValue(vCurDate);
        if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
            rdo_MKT_ID.setValue(scwin.gLdMktTp);
            rdo_MKT_ID.hide();
            label_4.hide();
            $c.cm.setColumnProp(grd_Grid, "LD_MKT_TP_NM", "show", false);
        } else {
            rdo_MKT_ID.setValue('9');
            rdo_MKT_ID.show("");
            label_4.show("");
            $c.cm.setColumnProp(grd_Grid, "LD_MKT_TP_NM", "show", true);
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35004.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar4(edt_SDate, 1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35004.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar4(edt_EDate, 2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35004.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name edt_SDate_OnLastChar
 * @description edt SDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_SDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(1); // if(시작일>종료일) 종료일=시작일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35004.edt_SDate_OnLastChar" });
    }
};

/**
 * @method
 * @name edt_EDate_OnLastChar
 * @description edt EDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_EDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(2); // if(시작일>종료일) 시작일=종료일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35004.edt_EDate_OnLastChar" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35004.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnFail
 * @description Grid On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnFail = async function() {
    try {
        await $c.win.alert("조회시 오류가 발생하였습니다. 시스템관리자에게 문의하세요");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35004.dts_Grid_OnFail" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert("조회시 오류가 발생하였습니다. 시스템관리자에게 문의하세요");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35004.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_Grid.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35004.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    try {
        const gNotiYn = dts_Grid.getCellData(row, "NOTI_YN");
        const gAcptNo = dts_Grid.getCellData(row, "ACPT_NO");
        if (colid === 'NOTI_YN') {
            if (gNotiYn === 'R') {
                const sbmOptions = {
                    id : "sbm_dts_UpdateList",
                    action : "/gauceSystemierAdaptor.do",
                    ref : "",
                    target : "dts_UpdateList=body.content",
                    isProcessMsg : false
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

                dts_UpdateList.insertRow();
                await scwin.save(gAcptNo);
            }
        } else if (colid === "DOC_TITLE") {
            await $c.stf.openDisclViewer(gAcptNo, "R");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35004.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", '유선통보 저장'));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35004.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", '유선통보 저장'));
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35004.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF35004.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "CB,SC 송수신 내역", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35004.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35004.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(gAcptNo) {
    const rtn = window.confirm('유선 통보하였습니까?');
    if (rtn === 1) {
        dts_UpdateList.setCellData(1, "ACPT_NO", gAcptNo);
        dts_UpdateList.setCellData(1, "EMP_NO", scwin.gEmpNo);
        trs_save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/AtsContactInfo.do",
            ref : "dts_UpdateList",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        return false;
    }
};
